mod greetings {
    pub fn hello() -> String {
        String::from("hello")
    }

    pub fn loud() -> String {
        // self:: starts in this module, super:: starts in the parent (the crate root here)
        super::shout(&self::hello())
    }

    pub mod formal {
        pub fn bow() -> String {
            // crate:: always starts at the top
            format!("{} (bows)", crate::greetings::loud())
        }
    }
}

fn main() {
    println!("{}", greetings::loud());
    println!("{}", greetings::formal::bow());
}

