exercise.solution:
mod math {
    pub fn square(n: i32) -> i32 {
        n * n
    }

    pub fn double(n: i32) -> i32 {
        n * 2
    }
}

fn main() {
    println!("{}", math::square(6));
    println!("{}", math::double(21));
}
